module protocol::app_t {

    use sui::test_scenario::{Self, Scenario};
    use sui::clock::Clock;

    use protocol::market::{Market};
    use protocol::app::{AdminCap, ProtocolApp};
    use protocol::market_t::setup_sample_market;
    use protocol::coin_decimals_registry::CoinDecimalsRegistry;

    /// A default market app setup
    public fun default_app_init<MarketType>(scenario: &mut Scenario, clock: &mut Clock, admin: address): (AdminCap, ProtocolApp, Market<MarketType>, CoinDecimalsRegistry) {
        let ctx = scenario.ctx();

        let (admin_cap, mut app) = protocol::app::init_t(ctx);
        let market_config = protocol::market_admin::create_market_config(&admin_cap, &app, 50, 1);

        let market_id = protocol::market_admin::register_market<MarketType>(&admin_cap, &mut app, market_config, clock, ctx);

        test_scenario::next_tx(scenario, admin);
        let mut market = scenario.take_shared_by_id<Market<MarketType>>(market_id);

        clock.set_for_testing(100 * 1000);
        let mut x_oracle = protocol::oracle_t::init_t(scenario);
        let coin_registry = setup_sample_market<MarketType>(
            &admin_cap,
            &mut app,
            &mut market,
            &mut x_oracle,
            clock,
            scenario
        );

        test_scenario::return_shared(x_oracle);

        (admin_cap, app, market, coin_registry)
    }
}

